        require(amount > 0);
        require(address(this).balance >= amount);

        // fund C so it has a balance to potentially withdraw
        c.call{value: amount}("");

        uint256 balanceBefore = address(c).balance;

        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the caller is not the owner, the call must revert and C must keep its balance.
        // Since this test contract is deployed as the caller during the checker run and is the owner only if it was set as such,
